 "content": "def transform(grid):
    """Paint selector-marker color, marking only aligned matching pattern cells."""
    h, w = len(grid), len(grid[0])
    sep_row = next((r for r in range(h) if len(set(grid[r])) == 1), None)
    if sep_row is not None:
        pattern = [row[:] for row in grid[:sep_row]]
        selector = [row[:] for row in grid[sep_row + 1:]]
        if not pattern or len(pattern) != len(selector) or len(pattern[0]) != len(selector[0]):
            raise ValueError('horizontal panels do not align')
    else:
        sep_col = next((c for c in range(w) if all(row[c] == grid[0][c] for row in grid)), None)
        if sep_col is None:
            raise ValueError('separator not found')
        pattern = [row[:sep_col] for row in grid]
        selector = [row[sep_col + 1:] for row in grid]
        if not pattern or any(len(a) != len(b) for a, b in zip(pattern, selector)):
            raise ValueError('vertical panels do not align')
    from collections import Counter
    bg = Counter(x for row in selector for x in row).most_common(1)[0][0]
    markers = {x for row in selector for x in row if x != bg}
    if len(markers) != 1:
        raise ValueError('selector must have one marker color')
    mark = markers.pop()
    return [[3 if selector[r][c] == mark and pattern[r][c] == mark else mark
             for c in range(len(pattern[0]))] for r in range(len(pattern))]

if __name__ == '__main__':
    pass
